(()=>{'use strict';
 let usageCache,usageTime=0,usageBusy=false;async function usage(){const box=document.querySelector('#wallet-provider-status');if(!box||usageBusy)return;usageBusy=true;try{if(!usageCache||Date.now()-usageTime>60000){usageCache=await api('/api/wallet/usage');usageTime=Date.now();}const d=usageCache;box.innerHTML='<p>��������� ���������� ���������: <strong>'+esc(String(d.count))+' / '+esc(String(d.limit))+'</strong> � ������� '+esc(String(d.remaining))+'</p><p>�����: '+esc(d.plan)+' � ����� ����� '+esc(String(d.resetDate))+'</p>'+(d.compatibility?.enabled?'<p>���� ����� �������� ����� �������� ������� �������� � ������� ������: <strong>'+esc(String(d.compatibility.pending))+'</strong>'+(d.compatibility.retrying?' � ��� ����� ��������: '+esc(String(d.compatibility.retrying)):'')+'</p>':'')+(d.trialExpiresAt?'<p class="notice">����� ����� ������ �� '+esc(new Date(d.trialExpiresAt).toLocaleDateString('ar-SA'))+'. ������� �������� ������� ���������� ��� ������� ����� ��� ������ ��� ������.</p>':'');}catch(e){box.textContent=e.message;}finally{usageBusy=false;}}const previous=render;render=function(){previous();if(window.RIJAA_DEMO||!serverMode||!principal)return;
 if(role==='admin'&&view==='health'&&!db.scopedBusiness){const main=document.querySelector('main');if(main&&!main.querySelector('#wallet-provider-status'))main.insertAdjacentHTML('beforeend','<section class="panel mt"><h2>Apple �Google Wallet</h2><div id="wallet-provider-status" aria-live="polite">���� ����� ��� �����υ</div></section>');usage();}if(principal.kind==='customer'&&clientStage==='card'){const host=document.querySelector('.enroll-issued-panel,.phone');if(host&&!host.querySelector('[data-wallet-issue]'))host.insertAdjacentHTML('beforeend','<div class="mt"><button class="btn primary full" data-wallet-issue>��� ������ ��� Apple / Google Wallet</button><p class="sub">���� ������� ������ ������� ������ ������� ��� �������. ���� ������ ����� ������� ���� ������� ������� ���.</p></div>');}
 if(role==='owner'&&view==='mycards'){const cards=Array.from(document.querySelectorAll('main article')).filter(el=>el.querySelector('[data-action="edit-program"]')||el.querySelector('h2'));const shops=db.shops.filter(s=>!s.archivedAt);cards.forEach((el,i)=>{const sh=shops[i];if(!sh)return;el.insertAdjacentHTML('beforeend','<button class="btn secondary full mt" data-wallet-preview="'+esc(sh.id)+'">����� ����� Wallet ���� �������</button>');});}
 };
 async function issue(button,preview){button.disabled=true;const prior=button.textContent;button.textContent='���� ����� ����� ������Ʌ';try{const id=preview||principal.shop;const result=await api('/api/wallet/issue',{shop:id,...(preview?{preview:true}:{}),...(db.scopedBusiness?{scope:db.scopedBusiness}:{})});const apple='/api/wallet/apple?shop='+encodeURIComponent(id)+(preview?'&preview=1':'')+(db.scopedBusiness?'&scope='+encodeURIComponent(db.scopedBusiness):'');modal(preview?'����� ����� Wallet':'������ ����� �������','<p>���� ����� �����. ��� ������� ����� �������� ������� ��������� �������Ǻ ���� ������� ������ ����� ��� ������� ��������.</p>'+(preview?'<p class="notice">��� ����� ������ ������� ��غ ����� �� ���� ������ �� ������ �����.</p>':'')+'<div class="actions"><a class="btn primary" href="'+esc(apple)+'">����� ��� Apple Wallet</a><a class="btn primary" target="_blank" rel="noopener noreferrer" href="'+esc(result.googleSaveUrl)+'">����� ��� Google Wallet</a></div><p class="sub">�� ����� ������� ������ ������� ��� Apple �Google �������� ������.</p>');}catch(e){toast(e.message);}finally{button.disabled=false;button.textContent=prior;}}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-wallet-issue],[data-wallet-preview]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();issue(b,b.dataset.walletPreview||'');},true);
})();
